"""Conservative target-tracking controller with safety gating, confirmation,
short-term reacquisition hysteresis, and heading-aware steering.
"""


# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Choose a safe action from the current target track and compact FSM memory.

    The controller stops on safety uncertainty, verifies newly acquired tracks,
    uses bounded alternating scan bursts after loss, and steers toward the
    target using bearing with heading-error fallback while respecting corridors.
    """
    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    scan_ticks = int(memory.get("scan_ticks", 0))
    last_action = memory.get("last_action", "")

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    heading_error = float(observation["heading_error"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])

    def emit(action, confidence, next_state):
        memory["state"] = next_state
        memory["last_action"] = action
        return action, confidence, memory

    # Safety is a hard gate and cannot be overridden by progress signals.
    if safety_confidence < 0.60 or closing_risk >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    # Require a sufficiently reliable, identity-consistent observation.
    confirmed = (
        visible
        and target_confidence >= 0.55
        and identity_confidence >= 0.60
    )
    if not confirmed:
        if state in {"LOCKED", "APPROACH", "VERIFY", "REACQUIRE"} or lost_steps > 0:
            if lost_steps <= 1:
                return emit("STOP", 0.92, "REACQUIRE")

            # Hold each scan direction briefly to reduce rapid instruction flips.
            if scan_ticks >= 2:
                scan_direction = (
                    "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
                )
                scan_ticks = 0
            scan_ticks += 1
            memory["scan_direction"] = scan_direction
            memory["scan_ticks"] = scan_ticks
            return emit(scan_direction, 0.74, "SEARCH")

        memory["scan_direction"] = scan_direction
        memory["scan_ticks"] = 1
        return emit(scan_direction, 0.72, "SEARCH")

    memory["scan_ticks"] = 0

    # Newly appearing tracks are approached cautiously until persistent.
    if track_age < 2:
        return emit("SLOW_DOWN", 0.80, "VERIFY")

    # Prefer bearing, but use heading error when the target is nearly centered.
    steer_error = bearing if abs(bearing) >= 4.0 else heading_error

    if distance == "near":
        if abs(heading_error) <= 15.0 and identity_confidence >= 0.80:
            return emit("ARRIVED", 0.96, "ARRIVED")

        if abs(steer_error) >= 5.0:
            action = "VEER_LEFT" if steer_error < 0 else "VEER_RIGHT"
            return emit(action, 0.87, "APPROACH")

        if observation["corridor_center"]:
            return emit("SLOW_DOWN", 0.84, "APPROACH")

    # Use a modest deadband for efficient straight travel, with corridor checks.
    if steer_error < -12.0 and observation["corridor_left"]:
        return emit("VEER_LEFT", 0.90, "APPROACH")
    if steer_error > 12.0 and observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.90, "APPROACH")
    if observation["corridor_center"]:
        return emit("FORWARD", 0.90, "APPROACH")

    # If the preferred side is unavailable, use the safest available fallback.
    if steer_error < 0.0 and observation["corridor_left"]:
        return emit("VEER_LEFT", 0.83, "APPROACH")
    if steer_error > 0.0 and observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.83, "APPROACH")
    if observation["corridor_left"]:
        return emit("VEER_LEFT", 0.80, "APPROACH")
    if observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.80, "APPROACH")

    return emit("STOP", 0.98, "STOPPED")


# EVOLVE-BLOCK-END
